"""The generated ``env.py`` driven by the bare ``alembic`` CLI.

Every case scaffolds a project with :meth:`AlembicHelper.init`, writes a
model module with an enum column used by two tables, and runs
``python -m alembic`` in a subprocess from the project root — the way
``uv run alembic downgrade -1`` runs, without the ``tempest`` CLI and
without any ``PYTHONPATH``. That covers three issues end to end:

* #451: the metadata import resolves through ``prepend_sys_path = .``
  (the control removes the line and gets ``ModuleNotFoundError``).
* #453: the autogenerated ``create_table`` carries no explicit
  ``CheckConstraint`` for the enum column, and SQLite still ends up with
  exactly one ``CHECK``, named by the convention.
* #454: the downgrade drops the ``ENUM`` type, so ``upgrade`` →
  ``downgrade`` → ``upgrade`` passes on PostgreSQL (marked ``docker``,
  run with ``make test-docker`` or ``TEST_POSTGRES_URL``).
"""

from __future__ import annotations

import asyncio
import os
import shutil
import sqlite3
import subprocess
import sys
import time
from collections.abc import Iterator
from pathlib import Path
from types import SimpleNamespace

import pytest
import sqlalchemy as sa
from sqlalchemy.ext.asyncio import create_async_engine

from tempest_fastapi_sdk import AlembicHelper
from tempest_fastapi_sdk.db.enum_migrations import type_bound_check_include_object
from tempest_fastapi_sdk.db.model import NAMING_CONVENTION

MODELS: str = '''"""Models for the generated-env tests."""

import enum

from sqlalchemy.orm import Mapped

from tempest_fastapi_sdk import BaseModel


class UserRole(enum.StrEnum):
    """Roles shared by both tables."""

    GUARDIAN = "GUARDIAN"
    TEEN = "TEEN"


class ThingModel(BaseModel):
    """First table holding the enum."""

    __tablename__ = "things"

    role: Mapped[UserRole]


class OtherModel(BaseModel):
    """Second table holding the same enum."""

    __tablename__ = "others"

    role: Mapped[UserRole]
'''
"""A model module whose two tables share one native enum type."""

POSTGRES_IMAGE: str = "postgres:16-alpine"
POSTGRES_CONTAINER: str = "tempest-alembic-env-live"
POSTGRES_PORT: int = 55463


def _scaffold(root: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Scaffold an Alembic project whose metadata comes from ``envmodels``.

    The scaffold runs from the project root, so ``script_location`` is
    the relative ``alembic`` a real project gets.

    Args:
        root (Path): The project root.
        monkeypatch (pytest.MonkeyPatch): Moves the working directory.

    Returns:
        Path: The same root, now holding ``alembic.ini``, ``alembic/``
        and the ``envmodels`` package.
    """
    package = root / "envmodels"
    package.mkdir()
    (package / "__init__.py").write_text(MODELS, encoding="utf-8")
    monkeypatch.chdir(root)
    AlembicHelper(config_path=str(root / "alembic.ini")).init(
        directory="alembic",
        metadata_module="envmodels",
    )
    return root


def _alembic(
    root: Path, database_url: str | None, *args: str
) -> subprocess.CompletedProcess[str]:
    """Run the bare Alembic CLI from the project root.

    ``-P`` keeps ``python -m`` from putting the working directory on
    ``sys.path``, which the ``alembic`` console script never does, and
    ``PYTHONPATH`` is removed: only ``prepend_sys_path`` can make the
    project importable. The interpreter's ``bin`` directory leads
    ``PATH`` so the ``ruff`` post-write hooks resolve.

    Args:
        root (Path): The project root.
        database_url (str | None): The ``DATABASE_URL`` the env resolves.
            ``None`` leaves the variable out of the child's environment,
            so the env script has to find the URL from the project
            itself.
        *args (str): The Alembic command and its arguments.

    Returns:
        subprocess.CompletedProcess[str]: The finished process.
    """
    env = {key: value for key, value in os.environ.items() if key != "PYTHONPATH"}
    if database_url is None:
        env.pop("DATABASE_URL", None)
    else:
        env["DATABASE_URL"] = database_url
    env["PATH"] = f"{Path(sys.executable).parent}{os.pathsep}{env.get('PATH', '')}"
    return subprocess.run(
        [sys.executable, "-P", "-m", "alembic", *args],
        cwd=root,
        env=env,
        capture_output=True,
        text=True,
        timeout=120,
    )


def _ok(process: subprocess.CompletedProcess[str]) -> None:
    """Fail with the process output when it did not exit cleanly.

    Args:
        process (subprocess.CompletedProcess[str]): The finished process.
    """
    assert process.returncode == 0, f"{process.stdout}\n{process.stderr}"


def _revision_source(root: Path) -> str:
    """Read the single revision autogenerate wrote.

    Args:
        root (Path): The project root.

    Returns:
        str: The revision file's source.
    """
    (revision,) = (root / "alembic" / "versions").glob("*.py")
    return revision.read_text(encoding="utf-8")


@pytest.fixture
def project(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Yield a freshly scaffolded project.

    Args:
        tmp_path (Path): Pytest's per-test directory.
        monkeypatch (pytest.MonkeyPatch): Moves the working directory.

    Returns:
        Path: The project root.
    """
    return _scaffold(tmp_path, monkeypatch)


class TestBareAlembicCli:
    def test_round_trip_on_sqlite(self, project: Path) -> None:
        url = f"sqlite+aiosqlite:///{project / 'app.db'}"
        _ok(_alembic(project, url, "revision", "--autogenerate", "-m", "init"))
        source = _revision_source(project)
        assert "CheckConstraint" not in source
        assert source.count("op.drop_enum_type(") == 1
        assert "op.drop_enum_type('user_role_enum')" in source.replace('"', "'")

        _ok(_alembic(project, url, "upgrade", "head"))
        _ok(_alembic(project, url, "downgrade", "-1"))
        _ok(_alembic(project, url, "upgrade", "head"))

        with sqlite3.connect(project / "app.db") as connection:
            (ddl,) = connection.execute(
                "SELECT sql FROM sqlite_master WHERE name = 'things'"
            ).fetchone()
        assert ddl.count("CHECK") == 1
        assert "CONSTRAINT ck_things_user_role_enum CHECK" in ddl

    def test_the_ini_works_from_outside_the_project_root(
        self,
        project: Path,
        tmp_path_factory: pytest.TempPathFactory,
    ) -> None:
        """Both paths in the ini are relative to the ini, not the cwd (#519).

        A FastAPI lifespan calling ``AlembicHelper("<abs>/alembic.ini")``
        runs from wherever the process was started; with
        ``script_location = alembic`` and ``prepend_sys_path = .`` that
        directory had to be the project root.
        """
        elsewhere = tmp_path_factory.mktemp("elsewhere")
        url = f"sqlite+aiosqlite:///{project / 'app.db'}"
        ini = str(project / "alembic.ini")
        _ok(_alembic(project, url, "-c", ini, "revision", "--autogenerate", "-m", "x"))
        env = {key: value for key, value in os.environ.items() if key != "PYTHONPATH"}
        env["DATABASE_URL"] = url
        process = subprocess.run(
            [sys.executable, "-P", "-m", "alembic", "-c", ini, "upgrade", "head"],
            cwd=elsewhere,
            env=env,
            capture_output=True,
            text=True,
            timeout=120,
        )
        _ok(process)
        with sqlite3.connect(project / "app.db") as connection:
            tables = {
                name
                for (name,) in connection.execute(
                    "SELECT name FROM sqlite_master WHERE type = 'table'"
                )
            }
        assert {"things", "others", "alembic_version"} <= tables
        lines = (project / "alembic.ini").read_text(encoding="utf-8").splitlines()
        assert "script_location = %(here)s/alembic" in lines
        assert "prepend_sys_path = %(here)s" in lines

    def test_metadata_import_needs_prepend_sys_path(self, project: Path) -> None:
        """Control: without the ini line the bare CLI cannot import the models."""
        ini = project / "alembic.ini"
        lines = ini.read_text(encoding="utf-8").splitlines()
        assert "prepend_sys_path = %(here)s" in lines
        ini.write_text(
            "\n".join(line for line in lines if not line.startswith("prepend_")),
            encoding="utf-8",
        )
        url = f"sqlite+aiosqlite:///{project / 'app.db'}"
        process = _alembic(project, url, "upgrade", "head")
        assert process.returncode != 0
        assert "No module named 'envmodels'" in process.stderr

    def test_custom_revision_hook_replaces_the_default(self, project: Path) -> None:
        env_py = project / "alembic" / "env.py"
        source = env_py.read_text(encoding="utf-8")
        env_py.write_text(
            source.replace(
                "run_alembic_env(target_metadata)",
                "def _empty(context, revision, directives):\n"
                "    directives[0].upgrade_ops.ops.clear()\n"
                "    directives[0].downgrade_ops.ops.clear()\n\n\n"
                "run_alembic_env(target_metadata, "
                "process_revision_directives=_empty)",
            ),
            encoding="utf-8",
        )
        url = f"sqlite+aiosqlite:///{project / 'app.db'}"
        _ok(_alembic(project, url, "revision", "--autogenerate", "-m", "empty"))
        source = _revision_source(project)
        assert "create_table" not in source
        assert "drop_enum_type" not in source


_DRIFT_COLUMN: str = (
    "    title: Mapped[str] = mapped_column(String(32), nullable=True)\n"
)
"""A column added to the model in the drift control."""


def _add_drift(root: Path) -> None:
    """Append a column to the model module so autogenerate sees real drift.

    Args:
        root (Path): The project root.
    """
    models = root / "envmodels" / "__init__.py"
    text = models.read_text(encoding="utf-8")
    text = text.replace(
        "from sqlalchemy.orm import Mapped\n",
        "from sqlalchemy import String\n"
        "from sqlalchemy.orm import Mapped, mapped_column\n",
    )
    text = text.replace(
        "    role: Mapped[UserRole]\n",
        f"    role: Mapped[UserRole]\n{_DRIFT_COLUMN}",
        1,
    )
    models.write_text(text, encoding="utf-8")


def _add_enum_member(root: Path) -> None:
    """Add a member to the shared enum so autogenerate sees real drift.

    Args:
        root (Path): The project root.
    """
    models = root / "envmodels" / "__init__.py"
    text = models.read_text(encoding="utf-8")
    text = text.replace(
        '    TEEN = "TEEN"\n', '    TEEN = "TEEN"\n    ADULT = "ADULT"\n'
    )
    models.write_text(text, encoding="utf-8")


class TestCheckOnSqlite:
    """``alembic check`` right after ``upgrade head`` on a SQLite enum (#483).

    The CHECK an ``Enum`` column carries is type-bound: Alembic reads it
    from the database but drops it from the metadata side, so ``check``
    used to report a phantom ``remove_constraint`` on a clean schema.
    """

    def test_check_passes_after_upgrade_head(self, project: Path) -> None:
        url = f"sqlite+aiosqlite:///{project / 'app.db'}"
        _ok(_alembic(project, url, "revision", "--autogenerate", "-m", "init"))
        _ok(_alembic(project, url, "upgrade", "head"))

        process = _alembic(project, url, "check")
        _ok(process)
        assert "No new upgrade operations detected" in process.stdout

    def test_check_still_reports_real_drift(self, project: Path) -> None:
        url = f"sqlite+aiosqlite:///{project / 'app.db'}"
        _ok(_alembic(project, url, "revision", "--autogenerate", "-m", "init"))
        _ok(_alembic(project, url, "upgrade", "head"))

        _add_drift(project)

        process = _alembic(project, url, "check")
        assert process.returncode != 0
        assert "add_column" in process.stdout
        assert "remove_constraint" not in process.stdout

    def test_check_reports_a_new_enum_member(self, project: Path) -> None:
        """#483: a changed enum member is drift, reported — not a crash."""
        url = f"sqlite+aiosqlite:///{project / 'app.db'}"
        _ok(_alembic(project, url, "revision", "--autogenerate", "-m", "init"))
        _ok(_alembic(project, url, "upgrade", "head"))

        _add_enum_member(project)

        process = _alembic(project, url, "check")
        assert process.returncode != 0
        assert "NotImplementedError" not in process.stderr
        assert "replace_enum" in process.stdout


@pytest.fixture(scope="module")
def postgres_url() -> Iterator[str]:
    """Yield a PostgreSQL URL: ``TEST_POSTGRES_URL`` or a fresh container.

    Yields:
        str: An asyncpg URL to an empty database.
    """
    configured = os.environ.get("TEST_POSTGRES_URL")
    if configured:
        yield configured
        return
    if shutil.which("docker") is None:
        pytest.skip("docker CLI not installed")
    if subprocess.run(["docker", "info"], capture_output=True).returncode != 0:
        pytest.skip("docker daemon not reachable")
    subprocess.run(["docker", "rm", "-f", POSTGRES_CONTAINER], capture_output=True)
    started = subprocess.run(
        [
            "docker",
            "run",
            "-d",
            "--name",
            POSTGRES_CONTAINER,
            "-e",
            "POSTGRES_PASSWORD=probe",
            "-e",
            "POSTGRES_DB=probe",
            "-p",
            f"{POSTGRES_PORT}:5432",
            POSTGRES_IMAGE,
        ],
        capture_output=True,
        text=True,
    )
    if started.returncode != 0:
        pytest.skip(f"could not start {POSTGRES_IMAGE}: {started.stderr.strip()}")
    try:
        deadline = time.monotonic() + 60
        while time.monotonic() < deadline:
            ready = subprocess.run(
                ["docker", "exec", POSTGRES_CONTAINER, "pg_isready", "-U", "postgres"],
                capture_output=True,
            )
            if ready.returncode == 0:
                break
            time.sleep(0.5)
        yield f"postgresql+asyncpg://postgres:probe@127.0.0.1:{POSTGRES_PORT}/probe"
    finally:
        subprocess.run(["docker", "rm", "-f", POSTGRES_CONTAINER], capture_output=True)


def _enum_types(url: str) -> list[str]:
    """List the enum types in the PostgreSQL database.

    Args:
        url (str): The asyncpg URL.

    Returns:
        list[str]: The ``typname`` of every enum type, sorted.
    """

    async def _read() -> list[str]:
        """Read ``pg_type`` over an async engine.

        Returns:
            list[str]: The enum type names, sorted.
        """
        engine = create_async_engine(url)
        try:
            async with engine.connect() as connection:
                rows = await connection.execute(
                    sa.text("SELECT typname FROM pg_type WHERE typtype = 'e'")
                )
                return sorted(row[0] for row in rows)
        finally:
            await engine.dispose()

    return asyncio.run(_read())


@pytest.mark.docker
def test_upgrade_downgrade_upgrade_on_postgresql(
    project: Path, postgres_url: str
) -> None:
    """The type leaves with the last table, so the second upgrade recreates it."""
    _ok(_alembic(project, postgres_url, "revision", "--autogenerate", "-m", "init"))
    assert "CheckConstraint" not in _revision_source(project)

    _ok(_alembic(project, postgres_url, "upgrade", "head"))
    assert _enum_types(postgres_url) == ["user_role_enum"]
    _ok(_alembic(project, postgres_url, "downgrade", "base"))
    assert _enum_types(postgres_url) == []
    _ok(_alembic(project, postgres_url, "upgrade", "head"))
    assert _enum_types(postgres_url) == ["user_role_enum"]
    _ok(_alembic(project, postgres_url, "downgrade", "base"))


_FACTORY_SETTINGS: str = '''"""Settings module with a zero-arg factory."""

from functools import lru_cache
from pathlib import Path

from tempest_fastapi_sdk.settings import DatabaseSettings

_ROOT = Path(__file__).resolve().parents[2]


class Settings(DatabaseSettings):
    """Settings for the test service."""


@lru_cache
def get_settings() -> Settings:
    """Build the settings, pointing the URL beside the project."""
    return Settings(DATABASE_URL=f"sqlite+aiosqlite:///{_ROOT / 'via_settings.db'}")
'''
"""A settings module that exposes a factory and no instance.

The SDK documents ``get_settings()`` as the accessor; before #490 the
generated ``env.py`` read ``settings`` by name and found nothing here, so
a project written that way could not migrate outside the ``tempest`` CLI.
The URL is written into the built object (not taken from the environment)
so its presence in the resolved URL proves the settings path, not the
``DATABASE_URL`` variable or the ``.env`` fallback.
"""


class TestBareAlembicWithoutDatabaseUrl:
    """#490: the generated ``env.py`` finds settings the CLI does.

    Runs ``python -m alembic`` with no ``DATABASE_URL`` in the child's
    environment, from the project root, so the only way the URL can be
    resolved is through the settings module or ``.env`` the SDK writes.
    """

    def _write_settings(
        self,
        root: Path,
        source: str,
        *,
        code_root: str = "src",
    ) -> None:
        """Write ``core/settings.py`` under the chosen code root.

        Args:
            root (Path): The project root.
            source (str): The module source.
            code_root (str): ``src`` or ``app``.
        """
        package: Path = root / code_root / "core"
        package.mkdir(parents=True)
        (root / code_root / "__init__.py").write_text("", encoding="utf-8")
        (package / "__init__.py").write_text("", encoding="utf-8")
        (package / "settings.py").write_text(source, encoding="utf-8")

    @pytest.mark.parametrize("code_root", ["src", "app"])
    def test_get_settings_factory_resolves_the_url(
        self,
        project: Path,
        code_root: str,
    ) -> None:
        """A factory-only module, no ``DATABASE_URL`` env, no ``.env``."""
        self._write_settings(project, _FACTORY_SETTINGS, code_root=code_root)
        _ok(_alembic(project, None, "current"))
        assert (project / "via_settings.db").is_file()

    def test_dotenv_is_read_when_the_module_has_no_settings(
        self,
        project: Path,
    ) -> None:
        """A settings file that yields nothing still leaves ``.env``."""
        self._write_settings(project, "VALUE = 1\n")
        (project / ".env").write_text(
            f"DATABASE_URL=sqlite+aiosqlite:///{project / 'via_dotenv.db'}\n",
            encoding="utf-8",
        )
        _ok(_alembic(project, None, "current"))
        assert (project / "via_dotenv.db").is_file()

    def test_import_error_reaches_the_error_message(
        self,
        project: Path,
    ) -> None:
        """The cause of a failed import is not swallowed into "empty"."""
        self._write_settings(
            project,
            'raise RuntimeError("boom-490-import")\n',
        )
        process = _alembic(project, None, "current")
        assert process.returncode != 0
        assert "boom-490-import" in process.stderr
        assert "DATABASE_URL is empty" in process.stderr

    def test_factory_error_reaches_the_error_message(
        self,
        project: Path,
    ) -> None:
        """#490: a factory that raised is not swallowed into "empty"."""
        self._write_settings(
            project,
            "from tempest_fastapi_sdk.settings import DatabaseSettings\n\n\n"
            "class Settings(DatabaseSettings):\n"
            "    pass\n\n\n"
            "def get_settings() -> Settings:\n"
            '    raise RuntimeError("boom-490-factory")\n',
        )
        process = _alembic(project, None, "current")
        assert process.returncode != 0
        assert "boom-490-factory" in process.stderr
        assert "DATABASE_URL is empty" in process.stderr


class TestTypeBoundCheckIncludeObject:
    """#483: the enum-check filter is scoped to the table that declares it."""

    @staticmethod
    def _declared_check(
        table_name: str,
        metadata: sa.MetaData,
    ) -> sa.CheckConstraint:
        """Build a table whose enum column carries a type-bound check.

        Args:
            table_name (str): The table to create.
            metadata (sa.MetaData): The metadata to attach it to.

        Returns:
            sa.CheckConstraint: The type-bound check SQLAlchemy built.
        """
        sa.Table(
            table_name,
            metadata,
            sa.Column(
                "kind",
                sa.Enum(
                    "a",
                    "b",
                    name=f"{table_name}_kind",
                    create_constraint=True,
                ),
            ),
        )
        for constraint in metadata.tables[table_name].constraints:
            if isinstance(constraint, sa.CheckConstraint) and getattr(
                constraint, "_type_bound", False
            ):
                return constraint
        raise AssertionError("the enum column declared no type-bound check")

    def test_a_check_of_the_same_name_on_another_table_is_kept(self) -> None:
        metadata = sa.MetaData(naming_convention=NAMING_CONVENTION)
        declared = self._declared_check("alpha", metadata)
        assert isinstance(declared.name, str)

        include = type_bound_check_include_object(metadata)
        same_table = SimpleNamespace(table=SimpleNamespace(name="alpha"))
        other_table = SimpleNamespace(table=SimpleNamespace(name="beta"))

        assert (
            include(same_table, declared.name, "check_constraint", True, None) is False
        )
        assert (
            include(other_table, declared.name, "check_constraint", True, None) is True
        )
